<section <?php echo nextsaas_section_attrs( 'about-us-principles', $attributes, array( 'section' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?>><div class="container"><div class="heading-row section-heading"><div><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2></div><p class="lead" data-nextsaas-rich="lead"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'lead' ) ); ?></p></div><div class="grid-3"><?php foreach ( $nextsaas_items as $nextsaas_index => $nextsaas_item ) : ?><article class="value-card"><span class="meta" data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_index ); ?>.meta"><?php echo nextsaas_rich( (string) ( $nextsaas_item['meta'] ?? '' ) ); ?></span><h3 data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_index ); ?>.heading"><?php echo nextsaas_rich( (string) ( $nextsaas_item['heading'] ?? '' ) ); ?></h3><p data-nextsaas-rich="items.<?php echo esc_attr( (string) $nextsaas_index ); ?>.body"><?php echo nextsaas_rich( (string) ( $nextsaas_item['body'] ?? '' ) ); ?></p></article><?php endforeach; ?></div></div></section>
